import{_ as t,o as a,c as e,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"12 · 自动化蓝图（把改画工作流变成服务）","description":"","frontmatter":{},"headers":[],"relativePath":"12-自动化蓝图.md","filePath":"12-自动化蓝图.md"}'),o={name:"12-自动化蓝图.md"};function i(r,s,l,p,d,h){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="_12-·-自动化蓝图-把改画工作流变成服务" tabindex="-1">12 · 自动化蓝图（把改画工作流变成服务）</h1><blockquote><p>阶段：<strong>未来规划</strong>（第 4 周以后才碰）。当前先跑通 02/03 本地闭环。 标注：✅ 本会话实测验证 / 🟡 官方文档确认 / ⚠️ 社区方案未验证。</p></blockquote><hr><h2 id="_1-目标架构-你的原话翻译成系统" tabindex="-1">1. 目标架构（你的原话翻译成系统）</h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Krita（本地，你画画）</span></span>
<span class="line"><span>   │  ① 你的画（PNG）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>本地脚本 / Krita 插件（你已有 kritarunner / Python 脚本能力）</span></span>
<span class="line"><span>   │  ② POST /upload/image + ③ POST /prompt（API 格式工作流 JSON）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>AutoDL 实例上的 ComfyUI（以 API 服务模式运行）</span></span>
<span class="line"><span>   │  ④ WebSocket 进度 → 执行 W1-A / W1-B / W5 通道</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>   │  ⑤ 输出：贴线版 / 理想版 / 并排对比图（工作流内自动拼图）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>本地归档（07 闭环：diff-notes + 对照图）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p><strong>自动化边界（方法论红线）</strong>：自动化到&quot;输出并排对比图 + 归档文件&quot;为止。<strong>自评与差异自读永远是你的环节</strong>——这是 08 文档里&quot;典型化主体是你&quot;的直接推论：机器可以替你跑重绘，不能替你判断&quot;哪里是缺点、哪里是特征&quot;。</p><h2 id="_2-comfyui-侧-它天生就是-api-服务-✅-已验证" tabindex="-1">2. ComfyUI 侧：它天生就是 API 服务（✅ 已验证）</h2><ul><li>ComfyUI 内置 HTTP + WebSocket API： <ul><li><code>POST /upload/image</code> —— 上传你的画（工作流里 Load Image 引用文件名）</li><li><code>POST /prompt</code> —— 提交 <strong>API 格式</strong>的工作流 JSON（<code>{节点id: {class_type, inputs}}</code>；UI 里&quot;导出 API 格式&quot;可得）</li><li>WebSocket —— 执行进度/完成事件</li><li><code>GET /view</code> / <code>/history</code> —— 取输出图</li></ul></li><li>官方文档章节（本会话 sitemap 实测确认路径）： <ul><li><a href="https://docs.comfy.org/development/comfyui-server/api-examples" target="_blank" rel="noreferrer">https://docs.comfy.org/development/comfyui-server/api-examples</a> （本地服务端 API 示例）</li><li><a href="https://docs.comfy.org/development/comfyui-server/comms_routes" target="_blank" rel="noreferrer">https://docs.comfy.org/development/comfyui-server/comms_routes</a> （HTTP/WS 路由）</li><li><a href="https://docs.comfy.org/development/comfyui-server/comms_overview" target="_blank" rel="noreferrer">https://docs.comfy.org/development/comfyui-server/comms_overview</a></li><li><a href="https://docs.comfy.org/development/api-development/workflow-api-format" target="_blank" rel="noreferrer">https://docs.comfy.org/development/api-development/workflow-api-format</a> （工作流 API 格式）</li><li><a href="https://docs.comfy.org/development/comfyui-server/api-key-integration" target="_blank" rel="noreferrer">https://docs.comfy.org/development/comfyui-server/api-key-integration</a> （API Key 集成）</li></ul></li><li>推荐封装：自己写一个 ~100 行的小服务（FastAPI）包在 ComfyUI 前面，做三件事： <ol><li><strong>认证</strong>（ComfyUI 本身无认证——直接暴露公网等于裸奔）</li><li>业务接口：<code>POST /redraw {image, 通道}</code> → 内部调 ComfyUI</li><li>结果装配：返回并排对比图 + 元数据（参数、种子、耗时）</li></ol></li><li>为什么自己封装而不是直连：AutoDL 的公网映射是&quot;任何人拿到 URL 就能提交&quot;（无鉴权）；封装层 = 你的 API 网关，还顺带把&quot;业务语义&quot;（贴线版/理想版）从&quot;裸工作流&quot;里解放出来。</li></ul><h2 id="_3-autodl-侧-随用随起的真实情况" tabindex="-1">3. AutoDL 侧：随用随起的真实情况</h2><h3 id="_3-1-关机-免费-✅-官方计费文档" tabindex="-1">3.1 关机 = 免费（✅ 官方计费文档）</h3><p>按量计费&quot;关机结束计费&quot;→ 生命周期策略：<strong>开机干活，干完自动关机</strong>。</p><h3 id="_3-2-脚本化关机-官方推荐模式-✅-官方省钱绝招文档原文" tabindex="-1">3.2 脚本化关机：官方推荐模式（✅ 官方省钱绝招文档原文）</h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train.py</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/usr/bin/shutdown</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 无论成败都关机</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train.py</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/usr/bin/shutdown</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 成功才关机</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或在 Python 里：os.system(&quot;/usr/bin/shutdown&quot;)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>官方文档（<a href="https://api.autodl.com/docs/save_money/" target="_blank" rel="noreferrer">https://api.autodl.com/docs/save_money/</a> ）场景三原话：适合&quot;不确定代码执行多久、希望执行完立马关机&quot;。</p><h3 id="_3-3-无卡模式-✅-官方文档" tabindex="-1">3.3 无卡模式（✅ 官方文档）</h3><p>0.5 核 / 2GB / 无 GPU，<strong>￥0.1/小时</strong>；同一主账号同时只能有一个无卡模式实例；用于传文件/修环境。</p><h3 id="_3-4-远程-脚本化开机-官方公开文档没有-⚠️-重要边界" tabindex="-1">3.4 远程&quot;脚本化开机&quot;：官方公开文档没有（⚠️ 重要边界）</h3><ul><li>AutoDL 公开文档索引中<strong>没有开放 API 章节</strong>（本会话实测 docs 索引）→ 官方不提供稳定的远程开机 API</li><li>社区存在 autodl-cli / Python SDK（号称基于&quot;应用实例 API&quot;，可开关机）——⚠️ <strong>未验证，且第三方方案随平台变动可能失效，不要把业务依赖在它上面</strong></li><li>替代路线：浏览器自动化（Playwright 登录控制台点开机）——脆弱，仅作个人玩具</li><li><strong>现实建议</strong>：你的使用模式是&quot;画画时用&quot;——开机后保持 GPU 模式（按秒计费，画画期间成本即实际时长），画完自动关机（3.2 的模式）。全自动远程开机是锦上添花，等官方 API 出现再说。</li></ul><h3 id="_3-5-开机自动拉起-comfyui-🟡-社区实践" tabindex="-1">3.5 开机自动拉起 ComfyUI（🟡 社区实践）</h3><p>社区做法：把&quot;启动 ComfyUI&quot;写进开机启动任务（systemd / 自启动脚本），开机后 1~3 分钟服务就绪。⚠️ AutoDL 具体配置方式以控制台/社区最新实践为准。</p><h2 id="_4-备选托管-不想管服务器时" tabindex="-1">4. 备选托管（不想管服务器时）</h2><table tabindex="0"><thead><tr><th>平台</th><th>模式</th><th>标注</th></tr></thead><tbody><tr><td><strong>fal.ai</strong></td><td>ComfyUI 工作流托管为 API，按次计费，无服务器</td><td>🟡 官方文档此前确认有 ComfyUI 支持（本会话复验时网络异常，未再次确认）</td></tr><tr><td><strong>Comfy Deploy</strong></td><td>ComfyUI 工作流部署平台（版本管理/认证/按次计费）</td><td>✅ <a href="https://www.comfydeploy.com" target="_blank" rel="noreferrer">https://www.comfydeploy.com</a> 实测可达</td></tr><tr><td><strong>RunPod Serverless</strong></td><td>ComfyUI 模板 + serverless 计费</td><td>🟡</td></tr></tbody></table><p>优点：随用随起是平台义务、自带认证；缺点：国内访问与支付门槛、输入/输出要走公网。</p><h2 id="_5-成本与延迟模型-按量计费下" tabindex="-1">5. 成本与延迟模型（按量计费下）</h2><table tabindex="0"><thead><tr><th>项</th><th>量级</th></tr></thead><tbody><tr><td>冷启动（关机→开机→ComfyUI 就绪）</td><td>1~3 分钟（开机启动任务自动拉起则无需人工）</td></tr><tr><td>单张重绘（预热后）</td><td>20~60 秒（4060 档；AutoDL 卡更快）</td></tr><tr><td>费用</td><td>按开机时长计（如 24G 卡几元/小时档）；画画的会话期间开着，干完自动关机</td></tr></tbody></table><h2 id="_6-mvp-路径-未来-按序推进" tabindex="-1">6. MVP 路径（未来，按序推进）</h2><ol><li><strong>第一步（本地先行）</strong>：ComfyUI 本地跑通 → 用官方 api-examples 文档手写一次&quot;脚本提交工作流、取回输出&quot;（在本地 127.0.0.1 上做，零成本，这就是 ComfyUI API 的&quot;从 NAND 到 CPU&quot;）</li><li><strong>第二步（上云）</strong>：把同一套脚本指向 AutoDL 实例（先手动开机），验证&quot;传图→重绘→取图&quot;闭环；加开机自动拉起 ComfyUI</li><li><strong>第三步（生命周期）</strong>：接入&quot;自动关机&quot;（3.2 模式）；评估是否值得上社区开机 CLI（⚠️ 不依赖）</li><li><strong>第四步（可选）</strong>：封装 FastAPI 业务层（认证 + 通道选择 + 并排图），Krita 插件调用</li></ol><h2 id="_7-验证记录" tabindex="-1">7. 验证记录</h2><p><strong>✅ 实测</strong>：ComfyUI 官方本地 API 文档章节存在（sitemap 确认 5 个页面路径）；Comfy Deploy 可达；AutoDL 省钱绝招文档（无卡模式 0.1 元/h、shutdown 模式）；AutoDL docs 索引无开放 API 章节 <strong>🟡/⚠️</strong>：fal.ai 复验失败（网络异常，此前会话确认过 ComfyUI 支持）；autodl-cli/SDK 未验证（README 404）；AutoDL 开机自启动配置方式未验证</p>`,29)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
